        if (!/^\s*\d*\s*$/.test(terms)) {
          setTermsRefused(true);
          if (editing !== '') {
            setEditing(undefined);
            setName('');
            setGrade('A');
            setGradeFrom('');
            setTerms('');
            setContact('');
          }
          return;
        }
        submitOnce(() => {
          clearError();
          return save.mutateAsync({ editing, name, grade, gradeFrom, terms, contact });
        });
      }}
